import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { SERVICE_SEGMENTS } from './service-segments';
import type { DirectorySpec, MessageDef, SegmentDef, SpecIndex } from './types';

/**
 * Loads the specifications generated by `npm run build:specs` (see `scripts/build-specs.ts`).
 */
export class SpecRegistry {
  private readonly index: SpecIndex;
  private readonly cache = new Map<string, DirectorySpec>();
  readonly specDir: string;

  /**
   * @param source directory containing the generated `index.json` and `<DIR>.json` files, or
   *   the generated specifications themselves (e.g. for use in a browser).
   */
  constructor(source: string | { index: SpecIndex; directories: DirectorySpec[] } = locateSpecDir()) {
    if (typeof source !== 'string') {
      this.specDir = '';
      this.index = source.index;
      for (const d of source.directories) this.cache.set(d.directory, d);
      return;
    }
    this.specDir = source;
    const file = join(source, 'index.json');
    if (!existsSync(file)) {
      throw new Error(`UN/EDIFACT specifications not found in ${source}. Run "npm run build:specs" first.`);
    }
    this.index = JSON.parse(readFileSync(file, 'utf8')) as SpecIndex;
  }

  /** Directory keys available, e.g. `['D00B', 'D13B', 'D16A', 'D21B', 'D95B']`. */
  directories(): string[] {
    return Object.keys(this.index.directories).sort();
  }

  /** Message types available in a directory. */
  messageTypes(directory: string): string[] {
    return this.index.directories[normaliseDirectory(directory)]?.messages ?? [];
  }

  directory(directory: string): DirectorySpec {
    const key = normaliseDirectory(directory);
    let spec = this.cache.get(key);
    if (!spec) {
      const entry = this.index.directories[key];
      if (!entry) {
        throw new Error(
          `UN/EDIFACT directory ${directory} is not available (available: ${this.directories().join(', ')})`,
        );
      }
      spec = JSON.parse(readFileSync(join(this.specDir, entry.file), 'utf8')) as DirectorySpec;
      this.cache.set(key, spec);
    }
    return spec;
  }

  hasMessage(directory: string, type: string): boolean {
    return this.messageTypes(directory).includes(type);
  }

  message(directory: string, type: string): MessageDef {
    const spec = this.directory(directory);
    const msg = spec.messages[type];
    if (!msg) {
      throw new Error(
        `Message ${type} is not defined in directory ${spec.directory} ` +
          `(available: ${Object.keys(spec.messages).join(', ')})`,
      );
    }
    return msg;
  }

  /** Segment definition: service segments from ISO 9735, all others from the UN directory. */
  segment(directory: string, tag: string): SegmentDef | undefined {
    return SERVICE_SEGMENTS[tag] ?? this.directory(directory).segments[tag];
  }
}

/** `D:21B`, `d21b`, `D21B` -> `D21B`. */
export function normaliseDirectory(directory: string): string {
  return directory.replace(/[^0-9A-Za-z]/g, '').toUpperCase();
}

/** Directory key from the UNH message identifier (S009 0052 version and 0054 release). */
export function directoryFromVersion(version: string, release: string): string {
  return normaliseDirectory(`${version}${release}`);
}

function locateSpecDir(): string {
  let dir = __dirname;
  for (let i = 0; i < 6; i++) {
    const candidate = join(dir, 'specs');
    if (existsSync(join(candidate, 'index.json'))) return candidate;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return join(__dirname, '..', '..', 'specs');
}

let defaultRegistry: SpecRegistry | undefined;
/** Replaces the registry used when no `registry` option is given (e.g. specs embedded in a web page). */
export function setDefaultRegistry(registry: SpecRegistry): void {
  defaultRegistry = registry;
}

export function getDefaultRegistry(): SpecRegistry {
  defaultRegistry ??= new SpecRegistry();
  return defaultRegistry;
}
